-- Base mestra de riscos ocupacionais (planilha de referência de 22/11/2026): 115 riscos em 6 categorias.
-- Idempotente. Para cada cliente: o que ainda não existe (mesmo nome, sem diferenciar maiúsculas) é criado; o que já
-- existe com o mesmo nome recebe o TEXTO padrão (descrição, danos, fonte, medidas, observações, código eSocial e tipo
-- de medição) e o valor anterior fica no histórico (audit_logs). As decisões do cliente (exposição, eSocial,
-- insalubridade, periculosidade, aposentadoria especial, ASO, EPC/EPI), os exames e os equipamentos NÃO são alterados.
CREATE TEMP TABLE _master (
  name text, category "RiskCategory", code text, description text, damage text, obs text, source text, admin text, meastype "EvaluationCriteria"
);
