INSERT INTO "audit_logs" ("id", "tenantId", "action", "entityType", "entityId", "metadata", "createdAt")
SELECT 'bm_' || md5(h."id" || 'antes'), h."tenantId", 'hazard.master_update', 'hazard', h."id",
  jsonb_build_object(
    'source', 'base-mestra-2026-11-22',
    'before', jsonb_build_object(
      'category', h."category"::text, 'esocialCode', h."esocialCode", 'description', h."description",
      'damagePotential', h."damagePotential", 'observations', h."observations",
      'sourceCircumstances', h."sourceCircumstances", 'adminMeasures', h."adminMeasures",
      'measurementType', h."measurementType"::text)),
  now()
FROM "hazards" h
JOIN _master m ON lower(btrim(h."name")) = lower(btrim(m.name))
WHERE h."deletedAt" IS NULL
ON CONFLICT ("id") DO NOTHING;

UPDATE "hazards" h SET
  "category" = m.category, "esocialCode" = m.code, "description" = m.description, "damagePotential" = m.damage,
  "observations" = m.obs, "sourceCircumstances" = m.source, "adminMeasures" = m.admin,
  "measurementType" = m.meastype, "updatedAt" = now()
FROM _master m
WHERE h."deletedAt" IS NULL AND lower(btrim(h."name")) = lower(btrim(m.name));

INSERT INTO "hazards" ("id", "tenantId", "category", "name", "description", "damagePotential", "esocialCode",
  "sourceCircumstances", "observations", "adminMeasures", "measurementType", "insertInAso", "updatedAt")
SELECT 'bm_' || md5(t."id" || m.name), t."id", m.category, m.name, m.description, m.damage, m.code,
  m.source, m.obs, m.admin, m.meastype, false, now()
FROM "tenants" t
CROSS JOIN _master m
WHERE NOT EXISTS (
  SELECT 1 FROM "hazards" h
  WHERE h."tenantId" = t."id" AND h."deletedAt" IS NULL AND lower(btrim(h."name")) = lower(btrim(m.name))
);

DROP TABLE _master;
